import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel source code
cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

__global__ void fused_mean_softmax_tanh_scale_kernel(
    const float* __restrict__ x,
    const float* __restrict__ bias,
    float* __restrict__ out,
    int B, int C, int D, int H, int W,
    float scaling_factor)
{
    int b = blockIdx.x;
    int h = blockIdx.y;
    int w = threadIdx.x;
    if (w >= W) return;

    extern __shared__ float means[];

    // Mean reduction over depth and bias addition
    for (int c = 0; c < C; ++c) {
        float sum = 0.0f;
        for (int d = 0; d < D; ++d) {
            // Input layout: N, C, D, H, W
            int idx = ((b * C + c) * D + d) * H * W + h * W + w;
            sum += x[idx];
        }
        float mean = sum / (float)D + bias[c];
        means[c * W + w] = mean;
    }
    __syncthreads();

    // Online softmax over C channels
    float max_val = -1e30f;
    for (int c = 0; c < C; ++c) {
        float val = means[c * W + w];
        if (val > max_val) max_val = val;
    }
    float exp_sum = 0.0f;
    for (int c = 0; c < C; ++c) {
        exp_sum += expf(means[c * W + w] - max_val);
    }

    // Softmax normalization, tanh activation and scaling
    for (int c = 0; c < C; ++c) {
        float val = means[c * W + w];
        float softmax_val = expf(val - max_val) / exp_sum;
        float out_val = tanhf(softmax_val) * scaling_factor;
        // Output layout: B, C, H, W (depth dimension will be unsqueezed in Python)
        int out_idx = ((b * C + c) * H + h) * W + w;
        out[out_idx] = out_val;
    }
}

torch::Tensor fused_mean_softmax_tanh_scale_cuda(
    torch::Tensor x,
    torch::Tensor bias,
    float scaling_factor)
{
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(bias.is_cuda(), "bias must be a CUDA tensor");
    TORCH_CHECK(x.dim() == 5, "x must be 5D");
    int B = x.size(0);
    int C = x.size(1);
    int D = x.size(2);
    int H = x.size(3);
    int W = x.size(4);
    auto out = torch::empty({B, C, H, W}, x.options());

    int threads = W;
    dim3 grid(B, H);
    int shared_mem_size = C * W * sizeof(float);
    fused_mean_softmax_tanh_scale_kernel<<<grid, threads, shared_mem_size>>>(
        x.data_ptr<float>(),
        bias.data_ptr<float>(),
        out.data_ptr<float>(),
        B, C, D, H, W,
        scaling_factor
    );
    return out;
}
"""

cpp_source = "torch::Tensor fused_mean_softmax_tanh_scale_cuda(torch::Tensor x, torch::Tensor bias, float scaling_factor);"

# Compile the inline CUDA code
fused_op = load_inline(
    name="fused_op",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["fused_mean_softmax_tanh_scale_cuda"],
    verbose=False,
    extra_cflags=[""],
    extra_ldflags=[""],
)


class ModelNew(nn.Module):
    """
    Optimized model with a custom CUDA kernel that fuses:
    - mean pooling over depth
    - bias addition
    - softmax over channels
    - tanh activation
    - scaling
    into a single pass, avoiding multiple global memory round-trips.
    """
    def __init__(self, in_channels, out_channels, kernel_size, stride, padding, scaling_factor):
        super(ModelNew, self).__init__()
        self.conv_transpose = nn.ConvTranspose3d(
            in_channels, out_channels, kernel_size, stride=stride, padding=padding
        )
        self.bias = nn.Parameter(torch.randn(1, out_channels, 1, 1, 1))
        self.scaling_factor = scaling_factor
        self.fused_op = fused_op

    def forward(self, x):
        # 3D transposed convolution
        x = self.conv_transpose(x)  # (B, C, D, H, W)
        # Fused kernel: mean(D) + bias + softmax(C) + tanh + scale
        x = self.fused_op.fused_mean_softmax_tanh_scale_cuda(
            x, self.bias.view(-1), self.scaling_factor
        )  # -> (B, C, H, W)
        x = x.unsqueeze(2)  # -> (B, C, 1, H, W) to match original keepdim=True behavior
        return x
